// План: .qa/e2e/specs/placement-writing.md (группа 1, тесты 1.1–1.10); кейсы PW-01…PW-10 (.qa/tests/placement-writing.md).
// Запасной путь (autotest-writer): window.confirm, setOffline, page.route и общий ребёнок на всю группу.
// Один QA-ребёнок на файл: в beforeAll создаётся профиль, чтение проходится без голоса до первого задания письма;
// тесты 1.1–1.8 работают с ещё не отправленным первым заданием, 1.9 — со вторым, 1.10 — доводит тест до C3.
// Не прогонять при записи — запуск по /qa-regress.
import { test, expect } from '../../fixtures';
import type { BrowserContext, Dialog, Page } from '@playwright/test';
import {
  SUBMIT_WRITING_RPC,
  annotateCleanup,
  createChild,
  levelLines,
  openSharedUserPage,
  passReading,
  passWriting,
  qaChildName,
  startPlacementAsChild,
} from '../placement-results/placement.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.describe.configure({ mode: 'serial' });

const SEND_ERROR = 'לא הצלחתי לשלוח — אולי אין אינטרנט. מה שכתבת שמור כאן.';

test.describe('Стартовый тест — письмо: черновик, отмена, подтверждение и сбои', () => {
  let context: BrowserContext;
  let kid: Page;
  let childId = '';
  let childName = '';
  let cleanupNoted = false;

  // Управляемый обработчик window.confirm: режим и текст последнего окна.
  let dialogMode: 'accept' | 'dismiss' = 'dismiss';
  const dialogs: string[] = [];
  const onDialog = (d: Dialog) => {
    dialogs.push(d.message());
    return dialogMode === 'accept' ? d.accept() : d.dismiss();
  };
  // Учёт обращений к анализу письма.
  let submitRequests = 0;
  let submitResponses = 0;

  const input = () => kid.getByTestId('writing-input');
  const sendButton = () => kid.getByRole('button', { name: 'שלחתי!', exact: true });

  test.beforeAll(async ({ browser }, testInfo) => {
    testInfo.setTimeout(6 * 60_000); // создание ребёнка + чтение (адаптивный цикл) — это не пауза
    ({ context, page: kid } = await openSharedUserPage(browser, testInfo, 'parent'));
    childName = qaChildName();
    childId = await createChild(kid, childName);
    await startPlacementAsChild(kid, childId, childName);
    await passReading(kid, 'קל');
    await expect(input()).toBeVisible();

    kid.on('dialog', onDialog);
    kid.on('request', (r) => { if (r.url().includes(SUBMIT_WRITING_RPC)) submitRequests++; });
    kid.on('response', (r) => { if (r.url().includes(SUBMIT_WRITING_RPC)) submitResponses++; });
  });

  test.beforeEach(async ({}, testInfo) => {
    // Ребёнок создаётся в beforeAll — имя и id для ручной чистки в каждом тесте группы (видно в отчёте).
    if (childId && !cleanupNoted) { annotateCleanup(testInfo, childName, childId); cleanupNoted = true; }
  });

  test.afterAll(async () => {
    await context?.close();
  });

  test('Поле письма без проверки правописания и без сетевых запросов при наборе @desktop @data #a0f00f', async () => {
    const field = input();
    // AC1 «אין ניתוח או תיקון בזמן הכתיבה»: браузер не подчёркивает и не исправляет
    await expect(field).toHaveAttribute('spellcheck', 'false');
    await expect(field).toHaveAttribute('autocorrect', 'off');
    await expect(field).toHaveAttribute('autocapitalize', 'none');
    await expect(field).toHaveAttribute('autocomplete', 'off');

    const during: string[] = [];
    const track = (r: { resourceType(): string; url(): string }) => {
      if (['fetch', 'xhr'].includes(r.resourceType())) during.push(r.url());
    };
    kid.on('request', track);
    await field.click();
    await field.pressSequentially('הילד קורא ספר');
    await expect(field).toHaveValue('הילד קורא ספר');
    kid.off('request', track);
    // AC1/AC3: во время набора нет ни одного запроса (анализ — только после подтверждения отправки)
    expect(during, 'запросы во время набора').toEqual([]);
    expect(submitRequests).toBe(0);
  });

  test('«ביטול פעולה» отменяет последний введённый символ @desktop @data #a0f00f', async () => {
    const field = input();
    const before = await field.inputValue();
    await field.click();
    await field.press('End');
    await field.pressSequentially('אב');
    await expect(field).toHaveValue(before + 'אב');

    const undo = kid.getByRole('button', { name: 'ביטול פעולה' });
    await undo.click();
    await expect(field).toHaveValue(before + 'א'); // AC2: отмена по символу
    await undo.click();
    await expect(field).toHaveValue(before);
  });

  test('«ניקוי» требует подтверждения; отказ сохраняет текст, «ביטול פעולה» возвращает очищенное @desktop @data #a0f00f', async () => {
    const field = input();
    const text = await field.inputValue();
    expect(text, 'в поле есть текст').not.toBe('');
    const clear = kid.getByRole('button', { name: 'ניקוי' });

    // Отказ в подтверждении — текст на месте
    dialogMode = 'dismiss';
    const n = dialogs.length;
    await clear.click();
    await expect.poll(() => dialogs.length).toBe(n + 1);
    expect(dialogs.at(-1)).toContain('לנקות את הכתיבה?'); // AC2 «ניקוי דורש אישור»
    await expect(field).toHaveValue(text);

    // Подтверждение — поле пустое
    dialogMode = 'accept';
    await clear.click();
    await expect.poll(() => dialogs.length).toBe(n + 2);
    expect(dialogs.at(-1)).toContain('לנקות את הכתיבה?');
    await expect(field).toHaveValue('');

    // «ביטול פעולה» возвращает очищенный текст
    await kid.getByRole('button', { name: 'ביטול פעולה' }).click();
    await expect(field).toHaveValue(text);
    dialogMode = 'dismiss';
  });

  test('Черновик сохраняется на ребёнка и задание и переживает обновление страницы @desktop @data #a0f00f', async () => {
    const field = input();
    const draft = 'טיוטה לפני שליחה';
    await field.fill(draft);

    // Черновик в localStorage, ключ вида benjico…writing-draft:<child>:<task>
    await expect
      .poll(() =>
        kid.evaluate((id) => {
          const keys = Object.keys(localStorage).filter((k) => k.includes('writing-draft') && k.includes(id));
          return keys.map((k) => localStorage.getItem(k) ?? '').join('|');
        }, childId),
      )
      .toContain(draft);

    await kid.reload();
    await expect(input()).toHaveValue(draft); // «טיוטה לפני שליחה» — описание тикета; FL-04 шаг 3
    expect(submitRequests, 'обновление не отправляет черновик').toBe(0);
  });

  test('Черновик переживает «השהיה» и возврат к письму @desktop @data #a0f00f', async () => {
    const draft = await input().inputValue();
    expect(draft).not.toBe('');

    await kid.getByRole('button', { name: 'השהיה' }).click();
    await kid.waitForURL((url) => !url.pathname.includes('/assessment/writing'));
    // TODO verify selector: путь возврата после паузы не зафиксирован — возвращаемся прямым адресом части письма (#8bf5a8).
    await kid.goto(`/${childId}/assessment/writing`);
    await expect(input()).toHaveValue(draft);
    expect(submitRequests).toBe(0);
  });

  test('Отмена подтверждения отправки — обработка не начинается, текст на месте @desktop @data #a0f00f', async () => {
    const field = input();
    const text = await field.inputValue();
    dialogMode = 'dismiss';
    const n = dialogs.length;

    await sendButton().click();
    await expect.poll(() => dialogs.length).toBe(n + 1);
    expect(dialogs.at(-1)).toContain('לשלוח לבנג׳י?'); // AC3 «עיבוד מתחיל רק לאחר אישור שליחה»
    await expect(kid.getByText('מעבדים…')).toBeHidden();
    await expect(field).toHaveValue(text);
    expect(submitRequests, 'submit_placement_writing не вызывался').toBe(0);
  });

  test('Сбой сервера при отправке (500) — понятное сообщение и «נסו שוב», текст цел @desktop @data #a0f00f', async () => {
    const field = input();
    const text = await field.inputValue();
    await kid.route(`**${SUBMIT_WRITING_RPC}*`, (route) =>
      route.fulfill({ status: 500, contentType: 'application/json', body: '{"message":"QA-AUTO forced 500"}' }),
    );
    try {
      dialogMode = 'accept';
      await sendButton().click();
      await expect(kid.getByText(SEND_ERROR)).toBeVisible();
      await expect(kid.getByRole('button', { name: 'נסו שוב', exact: true })).toBeVisible();
      await expect(field).toHaveValue(text); // FL-04 сбой: написанное не теряется; G5
    } finally {
      dialogMode = 'dismiss';
      await kid.unroute(`**${SUBMIT_WRITING_RPC}*`);
    }
  });

  test('Нет интернета при отправке — сообщение, текст цел, без автоотправки; «נסו שוב» отправляет и показывает «מעבדים…» @desktop @data #a0f00f', async () => {
    test.setTimeout(2 * 60_000);
    // Сбросить экран ошибки предыдущего теста: черновик восстановится из localStorage.
    await kid.reload();
    const field = input();
    await expect(field).not.toHaveValue('');
    const text = await field.inputValue();
    const responsesBefore = submitResponses;

    await context.setOffline(true);
    try {
      dialogMode = 'accept';
      await sendButton().click();
      await expect(kid.getByText(SEND_ERROR)).toBeVisible();
      await expect(kid.getByRole('button', { name: 'נסו שוב', exact: true })).toBeVisible();
      await expect(field).toHaveValue(text);
    } finally {
      await context.setOffline(false);
    }
    // Без автоотправки: после возврата сети ответа сервера не было, сообщение и кнопка на месте.
    // (Проверка мгновенная — фиксированной паузы нет по правилам; см. риски в плане.)
    expect(submitResponses).toBe(responsesBefore);
    await expect(kid.getByText(SEND_ERROR)).toBeVisible();

    // «נסו שוב» → обработка. Ответ сервера задерживаем, пока не увидим «מעבדים…» (без гонки и без пауз).
    let release!: () => void;
    const released = new Promise<void>((r) => (release = r));
    await kid.route(`**${SUBMIT_WRITING_RPC}*`, async (route) => {
      await released;
      await route.continue();
    });
    try {
      dialogMode = 'accept'; // если «נסו שוב» снова спросит подтверждение
      const submitted = kid.waitForResponse((r) => r.url().includes(SUBMIT_WRITING_RPC), { timeout: 60_000 });
      await kid.getByRole('button', { name: 'נסו שוב', exact: true }).click();
      await expect(kid.getByText('מעבדים…')).toBeVisible();
      await expect(kid.getByText('בנג׳י קורא את מה שכתבת')).toBeVisible();
      release();
      const resp = await submitted;
      expect(resp.ok()).toBeTruthy();
      await expect(kid.getByText('מעבדים…')).toBeHidden({ timeout: 60_000 });
    } finally {
      release();
      dialogMode = 'dismiss';
      await kid.unroute(`**${SUBMIT_WRITING_RPC}*`);
    }
  });

  test('Бессмысленный ответ «asdf» — «בואו ננסה עוד פעם!», ответ не записан @desktop @data #a0f00f', async () => {
    const field = input();
    await expect(field).toBeVisible({ timeout: 60_000 });
    await field.fill('asdf');
    dialogMode = 'accept';
    const submitted = kid.waitForResponse((r) => r.url().includes(SUBMIT_WRITING_RPC), { timeout: 60_000 });
    await sendButton().click();
    const resp = await submitted;
    expect(resp.ok()).toBeTruthy();
    const body = await resp.json();
    // TODO verify selector: форма ответа RPC (recorded на верхнем уровне или в массиве) не сверена.
    const recorded = Array.isArray(body) ? body[0]?.recorded : body?.recorded;
    expect(recorded, `ответ RPC: ${JSON.stringify(body)}`).toBe(false);
    // AC4 «חוסר ודאות יוצר בקשת ניסיון נוסף ולא קביעת כישלון»
    await expect(kid.getByText('בואו ננסה עוד פעם!')).toBeVisible();
    await expect(input()).toBeVisible();
    dialogMode = 'dismiss';
  });

  test('Результат письма — отдельная шкала 1–4 у родителя, чтение отдельно 1–10 @desktop @data #a0f00f', async ({ asUser }) => {
    test.setTimeout(6 * 60_000);
    // passWriting сам подтверждает окна через page.once — общий обработчик снимаем, чтобы окно не обрабатывалось дважды.
    kid.off('dialog', onDialog);
    await passWriting(kid, 'confident');
    await expect(kid.getByText(`כל הכבוד, ${childName}!`)).toBeVisible();

    // Зона родителя — отдельное окно, второй слот входа (#c121d3 AC3)
    const parent = await asUser('parent-3');
    await parent.goto(`/children/${childId}`);
    const lines = levelLines(parent);
    await expect(lines.block).toBeVisible();
    await expect(lines.writing).toHaveCount(1);
    await expect(lines.reading).toHaveCount(1);
    // AC5 «התוצאה מזינה רק את רמת הכתיבה בסולם ארבע הרמות»; F-05 «הסולם … אינו נגזר מסולם הקריאה»
    await expect(lines.writing).toHaveText(/כתיבה: .*[1-4] \/ 4/);
    await expect(lines.writing).not.toContainText('/ 10');
    await expect(lines.reading).toHaveText(/קריאה: .*(10|[1-9]) \/ 10/);
  });
});
